steps.codeExample:
// src/app/produtos/[slug]/page.tsx
export default async function ProdutoPage({
  params,
}: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  return <h1>Produto: {slug}</h1>;
}

